<script setup lang="ts">
import { computed, ref, onUnmounted } from 'vue';
import { state, scope, change, ui } from '../state';
import { clone } from '../services/application-state';
import type { ScheduleJob,ScheduleJobResult } from '../domain/schedule-worker-messages';
import { previewScheduleRegeneration } from '../domain/schedule-preview';
import ThemeWeekControls from './ThemeWeekControls.vue';
import type { PlannedWeek } from '../domain/models';
import { validateScheduleWeeks } from '../domain/scheduling';
import { HOMEWORK_LOCATION,locationOptions } from '../domain/planning-locations';
import { stageTarget } from '../domain/night-planning';
import UiIcon from '../components/UiIcon.vue';
import { swapScheduleWeeks } from '../domain/week-actions';
import { projectSchedule } from '../domain/scout-projection';
const settings=ref({...clone(state.value!.studio),requirementsPerStage:stageTarget(state.value!.studio.requirementsPerStage),weeks:state.value!.studio.schedule?.length?(state.value!.studio.weeks??state.value!.studio.schedule.length):10,preferredThemes:clone(state.value!.studio.preferredThemes??[]),allowedLocations:clone((state.value!.studio.allowedLocations??[]) as string[]),useLocations:true});
const themeSearch=ref('');
const themes=computed(()=>[...new Set(state.value!.requirements.flatMap(r=>(r.theme_tags as string[]|undefined)??r.tags))].sort());
const visibleThemes=computed(()=>themes.value.filter(t=>t.toLowerCase().includes(themeSearch.value.toLowerCase())));
const proposal=ref<PlannedWeek[]|null>(null),baseline=ref(''),summary=ref(''),editing=ref(-1),weekText=ref('');
const planning=ref(false),planningWeek=ref(0),planningTotal=ref(0);
let planner:Worker|null=null,jobVersion=0;
function stopPlanning(){jobVersion++;planner?.terminate();planner=null;planning.value=false;}
onUnmounted(stopPlanning);
const weeks=computed(()=>state.value!.studio.schedule??[]);
const assignmentScouts=computed(()=>state.value!.studio.strategy==='curriculum'?[]:scope.value);
const participation=computed(()=>projectSchedule(state.value!.requirements,state.value!.progress.scoutRecords,weeks.value,assignmentScouts.value,{useLocations:true,allowedLocations:(state.value!.studio.allowedLocations??[]) as string[],activities:state.value!.progress.activities??[]}));
const proposalParticipation=computed(()=>projectSchedule(state.value!.requirements,state.value!.progress.scoutRecords,proposal.value??[],settings.value.strategy==='curriculum'?[]:scope.value,{useLocations:settings.value.useLocations,allowedLocations:settings.value.allowedLocations,activities:state.value!.progress.activities??[]}));
const swapSource=ref(-1),swapTarget=ref(-1),swapBaseline=ref('');
const fingerprint=()=>JSON.stringify({state:state.value,scope:scope.value,settings:settings.value});
function preview(locks:boolean){
 stopPlanning();const version=jobVersion,start=fingerprint();proposal.value=null;planning.value=true;planningWeek.value=0;planningTotal.value=Number(settings.value.weeks)||10;
 try{
  planner=new Worker(new URL('../workers/schedule-worker.ts',import.meta.url),{type:'module'});
  planner.onmessage=(event:MessageEvent<ScheduleJobResult>)=>{
   if(version!==jobVersion)return;const message=event.data;
   if(message.type==='progress'){planningWeek.value=message.week;planningTotal.value=message.total;return;}
   stopPlanning();
   if(message.type==='error'){ui.error=message.message;return;}
   if(start!==fingerprint()){ui.error='Data, Scout scope or settings changed while planning. Generate a fresh preview.';return;}
   try{const delta=locks?previewScheduleRegeneration(weeks.value,message.weeks):null;summary.value=delta?`${delta.changedUnlockedWeeks} unlocked weeks change; ${delta.lockedWeeksPreserved} locked weeks preserved.`:`Replace schedule with ${message.weeks.length} weeks.`;proposal.value=message.weeks;baseline.value=start;}catch(e){ui.error=String(e);}
  };
  planner.onerror=event=>{if(version!==jobVersion)return;stopPlanning();ui.error=event.message||'The planner could not complete. Try fewer weeks or themes.';};
  const job:ScheduleJob={requirements:state.value!.requirements,records:state.value!.progress.scoutRecords,studio:settings.value,scouts:scope.value,keepLocks:locks,activities:state.value!.progress.activities??[]};
  planner.postMessage(clone(job));
 }catch(e){stopPlanning();ui.error=String(e);}
}
function apply(){if(baseline.value!==fingerprint()){ui.error='Data, preferences or Scout scope changed. Generate a fresh preview.';proposal.value=null;return;}if(change('Before schedule generation',s=>{Object.assign(s.studio,{strategy:settings.value.strategy,weeks:settings.value.weeks,requirementsPerStage:stageTarget(settings.value.requirementsPerStage),capacity:stageTarget(settings.value.requirementsPerStage)*3,preferredThemes:settings.value.preferredThemes,useLocations:settings.value.useLocations,allowedLocations:settings.value.allowedLocations,schedule:proposal.value!});})){proposal.value=null;swapSource.value=-1;editing.value=-1;}}
function lock(index:number,value:boolean){change('Before changing week lock',s=>{s.studio.schedule![index].locked=value;});settings.value.schedule=clone(weeks.value);}
function edit(index:number){editing.value=index;weekText.value=JSON.stringify(weeks.value[index],null,2);}
function saveWeek(){try{const week=JSON.parse(weekText.value) as PlannedWeek;validateScheduleWeeks([week],state.value!.requirements);if(change('Before week edit',s=>{if(s.studio.schedule![editing.value].locked)throw new Error('Unlock the week before editing.');s.studio.schedule![editing.value]=week;})){editing.value=-1;settings.value.schedule=clone(weeks.value);}}catch(e){ui.error=String(e);}}
function chooseSwap(index:number){swapSource.value=index;swapTarget.value=-1;swapBaseline.value=JSON.stringify(weeks.value);}
function applySwap(){if(swapBaseline.value!==JSON.stringify(weeks.value)){ui.error='The schedule changed. Choose the weeks to swap again.';swapSource.value=-1;return;}if(change('Before swapping weeks',s=>{s.studio.schedule=swapScheduleWeeks(s.studio.schedule??[],swapSource.value,swapTarget.value);})){settings.value.schedule=clone(weeks.value);swapSource.value=-1;editing.value=-1;}}
const locations=computed(()=>[...new Set([HOMEWORK_LOCATION,...state.value!.requirements.flatMap(r=>locationOptions(r))])]);
function setLocation(index:number,location:string){if(change('Before changing week location',s=>{if(s.studio.schedule![index].locked)throw new Error('Unlock the week before changing its location.');s.studio.schedule![index].location=location;}))settings.value.schedule=clone(weeks.value);}
function stageCount(w:PlannedWeek,stage:number){return state.value!.requirements.filter(r=>r.stage===stage&&w.requirementIds.includes(r.id)).length;}
function openStage(index:number,stage:number){ui.requirementId='' ;ui.stageSelection={weekIndex:index,weekId:weeks.value[index].id,stage};}
function requestedCount(w:PlannedWeek){return w.requirementsPerStage??(Number(w.stageLimit)||4);}
function stageActivityName(w:PlannedWeek,stage:number){const id=w.stageActivityIds?.[String(stage)];if(!id)return 'Choose a stage activity ↗';const activity=state.value!.progress.activities?.find(a=>a.id===id);return activity?String(activity.title||activity.name||activity.id):'Linked activity missing from bank';}
function stageNames(index:number,stage:number){return participation.value[index]?.stageScouts[String(stage)]??[];}
function stageNeeds(index:number,stage:number){return participation.value[index]?.stageCohorts[String(stage)]??[];}
function assignedCount(index:number){return Object.values(participation.value[index]?.stageScouts??{}).reduce((n,names)=>n+names.length,0);}
function cohortCount(index:number){return new Set(Object.values(participation.value[index]?.stageCohorts??{}).flat()).size;}
</script>
<template><section><p>Planning never marks Scout progress complete. Review the proposal before applying; regenerate preserves locked weeks.</p><p class="assignment-assumption">Assignments assume each selected Scout attends and demonstrates their planned skills. Names update when progress, Scout scope or week order changes. Every stage is offered where themes and locations allow. Readiness follows mandatory and recommended statement links; lower stages are a preference. Each Scout is assigned one activity, assumed completed by the end of the week. Other stage options receive no projected credit.</p><p v-if="!assignmentScouts.length" class="assignment-empty">Curriculum planning: choose Scouts and a Scout-based strategy to generate individual assignments.</p><details class="panel generation-settings" open><summary>Schedule generation settings</summary><div class="generation-body"><div class="toolbar"><label>Strategy<select v-model="settings.strategy"><option value="progress">Scout progress first</option><option value="curriculum">Curriculum first</option><option value="location">Location-focused</option><option value="balanced">Balanced</option></select></label><label>Weeks<input v-model.number="settings.weeks" type="number" min="1" max="60"></label><label>Requirements per stage / night<input v-model.number="settings.requirementsPerStage" type="number" min="1" max="12"></label><span class="stage-target-hint">Up to {{stageTarget(settings.requirementsPerStage)*3}} skills per night across 3 stages</span></div><fieldset><legend>Allowed locations · leave empty to allow all</legend><label v-for="location in locations" :key="location" class="check"><input v-model="settings.allowedLocations" type="checkbox" :value="location">{{location}}</label></fieldset><details class="panel schedule-theme-picker" open><summary>Prioritise themes · {{settings.preferredThemes.length}} selected</summary><p>Choose themes before generating. The scheduler compares your selected themes and allowed venues across all stages, prioritising prerequisite flow, then useful opportunities for each Scout. Related-theme fill-ins are marked Suggested; unrelated skills and incompatible locations are left out.</p><label>Find themes<input v-model="themeSearch" type="search" placeholder="Search themes"></label><fieldset class="theme-choice-grid"><legend>Themes to prioritise</legend><label v-for="theme in visibleThemes" :key="theme" class="check"><input v-model="settings.preferredThemes" type="checkbox" :value="theme">{{theme}}</label><p v-if="!visibleThemes.length">No matching themes.</p></fieldset><button v-if="settings.preferredThemes.length" @click="settings.preferredThemes=[]">Clear selected themes</button></details><div class="generation-actions"><div><strong>Ready to plan?</strong><p>Preview the whole schedule, or keep locked weeks and rebuild the rest.</p></div><button class="primary" :disabled="planning" @click="settings.schedule=clone(weeks);preview(false)">Generate schedule</button><button :disabled="planning||!weeks.length" @click="settings.schedule=clone(weeks);preview(true)">Regenerate unlocked</button></div></div></details>
 <section v-if="planning" class="planning-status" role="status"><strong>Comparing whole-night plans…</strong><span>Planned {{planningWeek}} / {{planningTotal}} weeks</span><button @click="stopPlanning">Cancel planning</button></section>
 <section v-if="proposal" class="panel"><h2>Schedule preview</h2><p>{{summary}} Changed unlocked weeks lose their existing activity attachments.</p><button @click="apply">Apply proposed schedule</button><button @click="proposal=null">Cancel</button><details><summary>Review proposal</summary><div v-for="(w,i) in proposal" :key="i" class="proposal-week"><strong>Week {{i+1}} {{w.locked?'(locked)':''}} · {{w.theme||w.title}} · {{w.location||'Flexible / anywhere'}}</strong><p v-if="proposalParticipation[i]?.unassignedScouts.length" class="stage-shortfall">Still needing work: {{proposalParticipation[i].unassignedScouts.join(', ')}}</p><p v-for="id in w.requirementIds" :key="id"><span v-if="w.suggestedRequirementIds?.includes(id)" class="suggestion-badge">Suggested</span> {{state!.requirements.find(r=>r.id===id)?.text}}<small v-if="scope.length&&settings.strategy!=='curriculum'" class="requirement-assignees">{{proposalParticipation[i]?.requirementScouts[id]?.join(', ')||'No Scouts assigned'}}</small></p><small v-for="stage in [1,2,3]" :key="stage">Stage {{stage}}: {{stageCount(w,stage)}} / {{requestedCount(w)}} planned. </small></div></details></section>
 <form v-if="editing>=0" class="panel" @submit.prevent="saveWeek"><h2>Edit Week {{editing+1}}</h2><label>Week fields (JSON)<textarea v-model="weekText" rows="18" /></label><button>Save week</button><button type="button" @click="editing=-1">Cancel</button></form>
 <div class="week-grid"><article v-for="(w,i) in weeks" :key="i" class="panel"><div class="toolbar"><h2>Week {{i+1}}</h2><div class="week-icon-actions"><button :class="['week-icon-button',{locked:w.locked}]" :aria-label="(w.locked?'Unlock':'Lock')+' Week '+(i+1)" :aria-pressed="!!w.locked" :title="w.locked?'Unlock week':'Lock week'" @click="lock(i,!w.locked)"><UiIcon :name="w.locked?'lock':'unlock'" /></button><button class="week-icon-button" :aria-label="'Swap Week '+(i+1)" title="Swap with another week" :disabled="!!w.locked||weeks.length<2" @click="chooseSwap(i)"><UiIcon name="swap" /></button></div></div><div v-if="swapSource===i" class="week-swap-picker"><label>Swap Week {{i+1}} with<select v-model.number="swapTarget" :aria-label="'Swap Week '+(i+1)+' with'"><option :value="-1" disabled>Choose another week</option><template v-for="(other,j) in weeks" :key="j"><option v-if="j!==i" :value="j" :disabled="!!other.locked">Week {{j+1}} · {{other.theme||other.title||'Unplanned'}}{{other.locked?' (locked)':''}}</option></template></select></label><p>Both complete plans exchange places, including their themes, skills and attachments.</p><button :disabled="swapTarget<0" @click="applySwap"><UiIcon name="swap" /> Swap weeks</button><button @click="swapSource=-1">Cancel</button></div><h3>{{w.title||'Unplanned'}}</h3><ThemeWeekControls :key="JSON.stringify(w)" :week="w" :index="i" /><label>Week {{i+1}} location<select :value="w.location||'Flexible / anywhere'" :aria-label="'Week '+(i+1)+' location'" :disabled="!!w.locked" @change="setLocation(i,($event.target as HTMLSelectElement).value)"><option>Flexible / anywhere</option><option v-for="location in [...new Set([...locations,...(w.location?[String(w.location)]:[])])]" :key="location">{{location}}</option></select></label><p class="week-capacity">Target: {{requestedCount(w)}} requirements in each stage</p><p v-if="assignmentScouts.length" class="week-cohort-summary">{{assignedCount(i)}} / {{cohortCount(i)}} Scouts needing work have a plan</p><details v-if="participation[i]?.unassignedScouts.length" class="unassigned-scouts" open><summary>{{participation[i].unassignedScouts.length}} Scouts still need suitable work</summary><p v-for="scout in participation[i].unassignedScouts" :key="scout"><strong>{{scout}}</strong><span>{{participation[i].unassignedReasons[scout]}}</span></p></details><details v-if="participation[i]?.warnings.length" class="assignment-warnings"><summary>{{w.locked?'Locked plan':'Plan'}} needs attention · {{participation[i].warnings.length}}</summary><p v-for="warning in participation[i].warnings" :key="warning">{{warning}}</p><p>Assignments were recalculated; planned skills have not been changed.</p></details><div v-for="stage in [1,2,3]" :key="stage"><div class="week-stage-heading"><button class="stage-open-button" :aria-label="'Open Week '+(i+1)+' Stage '+stage+' details'" @click="openStage(i,stage)">Stage {{stage}} <span>{{stageNames(i,stage).length}} / {{stageNeeds(i,stage).length}} eligible Scouts</span><span aria-hidden="true">↗</span></button><small>{{stageCount(w,stage)}} / {{requestedCount(w)}} planned</small></div><p v-if="w.stageShortfalls?.[String(stage)]" class="stage-shortfall">{{w.stageShortfalls[String(stage)]}} short — no more distinct, related, location-compatible statements are available.</p><p class="stage-activity-summary">{{assignmentScouts.length&&!stageNeeds(i,stage).length?'No Scouts assigned · alternative stage option':stageActivityName(w,stage)}}</p><div class="week-skill-list"><button v-for="r in state!.requirements.filter(r=>w.requirementIds.includes(r.id)&&r.stage===stage)" :key="r.id" :class="['week-skill-card',{suggested:w.suggestedRequirementIds?.includes(r.id)}]" @click="ui.requirementId=r.id"><span aria-hidden="true">{{w.suggestedRequirementIds?.includes(r.id)?'✧':'◇'}}</span><span>{{r.text}}<small v-if="assignmentScouts.length&&!participation[i]?.requirementScouts[r.id]?.length" class="opportunity-only">Stage option · no projected Scout credit</small><small v-if="participation[i]?.conditionalScouts[r.id]?.length" class="conditional-assignment">Assumes earlier planned evidence</small><small v-if="w.suggestedRequirementIds?.includes(r.id)" class="suggestion-badge">Suggested · {{w.suggestionThemes?.[r.id]?.join(', ')||'related theme'}}</small></span></button></div></div><button :disabled="!!w.locked" @click="edit(i)">Edit skills and settings</button><details v-if="w.activity"><summary>Stored attachment</summary><pre>{{JSON.stringify(w.activity,null,2)}}</pre></details></article></div><p v-if="!weeks.length">Generate a schedule or import an existing one in Data & State.</p></section></template>
